DROP TABLE IF EXISTS `discountstable`;
CREATE VIEW discountstable AS select `food_discounts`.`id` AS `id`,`food_discounts`.`code` AS `code`,`food_discounts`.`name` AS `name`,case when `food_discounts`.`min_order` = 0 then 'بدون حد ادنى' else `food_discounts`.`min_order` end collate utf8mb4_general_ci AS `min_order`,case when `food_discounts`.`max_user_use` = 0 then 'بدون حد اقصى' else `food_discounts`.`max_user_use` end collate utf8mb4_general_ci AS `max_user_use`,case when `food_discounts`.`max_uses` = 0 then 'بدون حد اقصى' else `food_discounts`.`max_uses` end collate utf8mb4_general_ci AS `max_uses`,case when `food_discounts`.`active` = 2 then date_format(from_unixtime(`food_discounts`.`start_date`),'%Y-%m-%d %h:%i:%s %p') else '' end AS `start_date`,case when `food_discounts`.`active` = 2 then date_format(from_unixtime(`food_discounts`.`end_date`),'%Y-%m-%d %h:%i:%s %p') else '' end AS `end_date`,`food_discounts`.`locations_type` AS `locations_type`,`food_discounts`.`categories_type` AS `categories_type`,`food_discounts`.`items_type` AS `items_type`,`food_discounts`.`phone` AS `phone`,`food_discounts`.`discount_type` AS `discount_type`,case when `food_discounts`.`discount_value_type` = 0 then concat(`food_discounts`.`discount_value`,' ج.م') when `food_discounts`.`discount_value_type` = 1 then concat(`food_discounts`.`discount_value`,' %') end collate utf8mb4_general_ci AS `discount_value`,`food_discounts`.`discount_value_type` AS `discount_value_type`,case when `food_discounts`.`max_discount` = 0 then 'بدون حد اقصى' else `food_discounts`.`max_discount` end collate utf8mb4_general_ci AS `max_discount`,`food_discounts`.`active` AS `active`,case when `food_discounts`.`active` = 1 then 1 when `food_discounts`.`active` = 2 and unix_timestamp() > `food_discounts`.`start_date` and unix_timestamp() < `food_discounts`.`end_date` then 1 else 0 end AS `active_status`,(select count(0) from `food_orders` where `food_orders`.`discount_id` = `food_discounts`.`id`) AS `total_uses`,(select count(distinct `food_orders`.`client_phone`) from `food_orders` where `food_orders`.`discount_id` = `food_discounts`.`id`) AS `total_users` from `food_discounts`;

DROP TABLE IF EXISTS `itemstable`;
CREATE VIEW itemstable AS select `food_items`.`id` AS `id`,`food_items`.`cat_id` AS `cat_id`,`food_items`.`title` AS `title`,`food_items`.`description` AS `description`,`food_items`.`img` AS `img`,concat(`food_items`.`tax`,' ',(select `website_settings`.`value` from `website_settings` where `website_settings`.`title` = 'currency')) AS `tax`,case when `food_items`.`price` > 0 then concat(`food_items`.`price`,' ',(select `website_settings`.`value` from `website_settings` where `website_settings`.`title` = 'currency')) else 'السعر حسب الاختيار' end AS `price`,concat(`food_items`.`before_discount`,' ',(select `website_settings`.`value` from `website_settings` where `website_settings`.`title` = 'currency')) AS `before_discount`,`food_items`.`active` AS `active`,case when `food_items`.`active` = 1 then 1 when `food_items`.`active` = 2 and unix_timestamp() > `food_items`.`from` and unix_timestamp() < `food_items`.`to` then 1 else 0 end AS `active_Status`,case when `food_items`.`active` = 2 then date_format(from_unixtime(`food_items`.`from`),'%Y-%m-%d %h:%i:%s %p') else '' end AS `start`,case when `food_items`.`active` = 2 then date_format(from_unixtime(`food_items`.`from`),'%Y-%m-%d %h:%i:%s %p') else '' end AS `end` from `food_items`;

DROP TABLE IF EXISTS `logstable`;
CREATE VIEW logstable AS select `logging`.`id` AS `id`,`logging`.`page` AS `page`,(select `panel_user`.`nickname` from `panel_user` where `panel_user`.`id` = `logging`.`admin`) AS `admin`,`logging`.`log` AS `log`,case when `logging`.`date` is not null then `logging`.`date` else '' end AS `logDate`,`logging`.`ip` AS `ip` from `logging`;

DROP TABLE IF EXISTS `orderstable`;
CREATE VIEW orderstable AS with CalculatedColumns as (select `f`.`id` AS `id`,`f`.`client_name` AS `client_name`,`f`.`client_phone` AS `client_phone`,`f`.`client_branch` AS `client_branch`,`f`.`client_area_name` AS `client_area_name`,`f`.`client_address` AS `client_address`,`f`.`client_notice` AS `client_notice`,`f`.`method` AS `method`,date_format(from_unixtime(`f`.`ordered_date`),'%Y-%m-%d %h:%i:%s %p') AS `order_date`,date_format(from_unixtime(`f`.`marked_date`),'%Y-%m-%d %h:%i:%s %p') AS `accept_date`,date_format(from_unixtime(`f`.`canceled_date`),'%Y-%m-%d %h:%i:%s %p') AS `canceled_date`,`f`.`marked` AS `marked`,(select `p`.`nickname` from `panel_user` `p` where `p`.`id` = `f`.`accepted_by`) AS `accepted_by`,(select `p`.`nickname` from `panel_user` `p` where `p`.`id` = `f`.`canceled_by`) AS `canceled_by`,`f`.`discount_name` AS `discount_name`,`f`.`discount_code` AS `discount_code`,`f`.`discount_id` AS `discount_id`,`f`.`tax` AS `tax`,`f`.`delivery_discount` + `f`.`total_discount` AS `discount`,`f`.`address_price` AS `address_price`,(select sum(`c`.`item_count` * `c`.`item_price`) from `food_order_cart` `c` where `c`.`order_id` = `f`.`id`) + coalesce((select sum(`c`.`item_count` * `c2`.`option_price`) from (`food_order_cart` `c` join `food_order_options` `c2` on(`c`.`id` = `c2`.`order_card_id`)) where `c`.`order_id` = `f`.`id`),0) AS `total_cart` from `food_orders` `f`)select `calculatedcolumns`.`id` AS `id`,`calculatedcolumns`.`client_name` AS `client_name`,`calculatedcolumns`.`client_phone` AS `client_phone`,`calculatedcolumns`.`client_branch` AS `client_branch`,`calculatedcolumns`.`client_area_name` AS `client_area_name`,`calculatedcolumns`.`client_address` AS `client_address`,`calculatedcolumns`.`client_notice` AS `client_notice`,`calculatedcolumns`.`method` AS `method`,`calculatedcolumns`.`order_date` AS `order_date`,`calculatedcolumns`.`accept_date` AS `accept_date`,`calculatedcolumns`.`canceled_date` AS `canceled_date`,`calculatedcolumns`.`marked` AS `marked`,`calculatedcolumns`.`accepted_by` AS `accepted_by`,`calculatedcolumns`.`canceled_by` AS `canceled_by`,`calculatedcolumns`.`discount_name` AS `discount_name`,`calculatedcolumns`.`discount_code` AS `discount_code`,`calculatedcolumns`.`discount_id` AS `discount_id`,`calculatedcolumns`.`tax` AS `tax`,`calculatedcolumns`.`discount` AS `discount`,`calculatedcolumns`.`address_price` AS `address_price`,`calculatedcolumns`.`total_cart` AS `total_cart`,`calculatedcolumns`.`total_cart` + `calculatedcolumns`.`address_price` + `calculatedcolumns`.`tax` - `calculatedcolumns`.`discount` AS `total_order` from `calculatedcolumns`;